class Solution {
public:
    vector<int> getBiggestThree(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        set<int> sums;

        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                sums.insert(grid[r][c]);
                for (int k = 1; r - k >= 0 && r + k < m && c - k >= 0 && c + k < n; ++k) {
                    int total = 0;
                    for (int i = 0; i < k; ++i) {
                        total += grid[r - k + i][c + i];
                        total += grid[r + i][c + k - i];
                        total += grid[r + k - i][c - i];
                        total += grid[r - i][c - k + i];
                    }
                    sums.insert(total);
                }
            }
        }

        vector<int> ans(sums.rbegin(), sums.rend());
        if (ans.size() > 3) ans.resize(3);
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] getBiggestThree(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        TreeSet<Integer> sums = new TreeSet<>(Collections.reverseOrder());

        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                sums.add(grid[r][c]);
                for (int k = 1; r - k >= 0 && r + k < m && c - k >= 0 && c + k < n; ++k) {
                    int total = 0;
                    for (int i = 0; i < k; ++i) {
                        total += grid[r - k + i][c + i];
                        total += grid[r + i][c + k - i];
                        total += grid[r + k - i][c - i];
                        total += grid[r - i][c - k + i];
                    }
                    sums.add(total);
                }
            }
        }

        int count = Math.min(3, sums.size());
        int[] ans = new int[count];
        Iterator<Integer> it = sums.iterator();
        for (int i = 0; i < count; ++i) {
            ans[i] = it.next();
        }
        return ans;
    }
}

