var getBiggestThree = function(grid) {
    const m = grid.length, n = grid[0].length;
    const sums = new Set();

    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            sums.add(grid[r][c]);
            for (let k = 1; r - k >= 0 && r + k < m && c - k >= 0 && c + k < n; ++k) {
                let total = 0;
                for (let i = 0; i < k; ++i) {
                    total += grid[r - k + i][c + i];
                    total += grid[r + i][c + k - i];
                    total += grid[r + k - i][c - i];
                    total += grid[r - i][c - k + i];
                }
                sums.add(total);
            }
        }
    }

    const sorted = [...sums].sort((a, b) => b - a);
    return sorted.slice(0, 3);
};
